"""OpenCode Dashboard — interactive TUI for monitoring sessions, costs, agents."""

from __future__ import annotations

from datetime import datetime, timezone

from textual.app import App, ComposeResult
from textual.binding import Binding
from textual.containers import Horizontal, Vertical, VerticalScroll
from textual.reactive import reactive
from textual.widgets import DataTable, Footer, Header, Label, Static

from data import (
    AgentCost,
    DailyCost,
    ModelCost,
    Overview,
    SessionRow,
    SubagentTree,
    format_cost,
    format_tokens,
    get_agent_costs,
    get_daily_costs,
    get_model_costs,
    get_overview,
    get_sessions,
    get_subagent_trees,
    get_tool_usage,
)


class OverviewPanel(Static):
    """Top-level stats bar."""

    data: reactive[Overview | None] = reactive(None)

    def render(self) -> str:
        if not self.data:
            return "Loading..."
        d = self.data
        return (
            f"[bold cyan]Sessions[/]: {d.total_sessions}  "
            f"[bold green]Cost[/]: {format_cost(d.total_cost)}  "
            f"[bold yellow]Input[/]: {format_tokens(d.total_input_tokens)}  "
            f"[bold yellow]Output[/]: {format_tokens(d.total_output_tokens)}  "
            f"[bold magenta]Reasoning[/]: {format_tokens(d.total_reasoning_tokens)}  "
            f"[bold blue]Cache[/]: {format_tokens(d.total_cache_read)}  "
            f"[dim]Agents[/]: {d.active_agents}  "
            f"[dim]Models[/]: {d.unique_models}  "
            f"[dim]Period[/]: {d.date_range}"
        )


class ModelCostTable(Static):
    """Model cost breakdown table."""

    data: reactive[list[ModelCost]] = reactive(list)

    def render(self) -> str:
        if not self.data:
            return "[dim]No model data[/]"
        lines = [
            f"[bold]{'Model':<35} {'Provider':<20} {'Sess':>5} {'Cost':>10} {'In':>10} {'Out':>10}[/]"
        ]
        lines.append("[dim]" + "─" * 95 + "[/]")
        for m in self.data[:12]:
            cost_str = format_cost(m.total_cost)
            lines.append(
                f"  {m.model:<33} {m.provider:<20} {m.session_count:>5} "
                f"{cost_str:>10} {format_tokens(m.input_tokens):>10} "
                f"{format_tokens(m.output_tokens):>10}"
            )
        return "\n".join(lines)


class AgentCostTable(Static):
    """Agent cost breakdown table."""

    data: reactive[list[AgentCost]] = reactive(list)

    def render(self) -> str:
        if not self.data:
            return "[dim]No agent data[/]"
        lines = [
            f"[bold]{'Agent':<30} {'Sess':>5} {'Cost':>10} {'In':>10} {'Out':>10}[/]"
        ]
        lines.append("[dim]" + "─" * 70 + "[/]")
        for a in self.data[:15]:
            cost_str = format_cost(a.total_cost)
            bar_len = min(20, int(a.total_cost / max(0.01, self.data[0].total_cost) * 20)) if self.data else 0
            bar = "█" * bar_len + "░" * (20 - bar_len)
            lines.append(
                f"  {a.agent:<28} {a.session_count:>5} {cost_str:>10} "
                f"{format_tokens(a.input_tokens):>10} {format_tokens(a.output_tokens):>10}  "
                f"[cyan]{bar}[/]"
            )
        return "\n".join(lines)


class DailyCostChart(Static):
    """Daily cost trend as ASCII sparkline."""

    data: reactive[list[DailyCost]] = reactive(list)

    def render(self) -> str:
        if not self.data:
            return "[dim]No daily data[/]"
        lines = ["[bold]Daily Cost Trend (last 14 days)[/]"]
        lines.append("[dim]" + "─" * 60 + "[/]")
        max_cost = max((d.total_cost for d in self.data), default=1) or 1
        bar_max = 35
        for d in reversed(self.data):
            bar_len = int(d.total_cost / max_cost * bar_max) if max_cost > 0 else 0
            bar = "▓" * bar_len + "░" * (bar_max - bar_len)
            cost_str = format_cost(d.total_cost)
            lines.append(
                f"  {d.date}  [green]{bar}[/]  {cost_str:>8}  ({d.session_count} sess)"
            )
        return "\n".join(lines)


class SubagentTreePanel(Static):
    """Subagent parent-child tree."""

    data: reactive[list[SubagentTree]] = reactive(list)

    def render(self) -> str:
        if not self.data:
            return "[dim]No subagent trees found[/]"
        lines = ["[bold]Subagent Trees (top 8)[/]"]
        lines.append("[dim]" + "─" * 60 + "[/]")
        for tree in self.data[:8]:
            lines.append(
                f"  [bold cyan]▼[/] [bold]{tree.parent_title}[/] "
                f"({len(tree.children)} children)"
            )
            for child in tree.children[:5]:
                cost_str = format_cost(child.cost)
                lines.append(
                    f"    [dim]├─[/] {child.model:<25} {cost_str:>8}  "
                    f"{child.time_created.strftime('%m-%d %H:%M')}"
                )
            if len(tree.children) > 5:
                lines.append(f"    [dim]└─ ... +{len(tree.children) - 5} more[/]")
        return "\n".join(lines)


class SessionList(Static):
    """Recent sessions list."""

    data: reactive[list[SessionRow]] = reactive(list)

    def render(self) -> str:
        if not self.data:
            return "[dim]No sessions[/]"
        lines = [
            f"[bold]{'Title':<40} {'Model':<25} {'Agent':<18} {'Cost':>8} {'Tok In':>8} {'Tok Out':>8}  {'When'}[/]"
        ]
        lines.append("[dim]" + "─" * 120 + "[/]")
        for s in self.data[:20]:
            prefix = "  " if not s.is_subagent else "  [dim]└[/]"
            title = s.title[:38]
            cost_str = format_cost(s.cost)
            time_str = s.time_created.strftime("%m-%d %H:%M")
            agent_display = s.agent[:16] if s.agent else "[dim]—[/]"
            lines.append(
                f"{prefix}{title:<40} {s.model:<25} {agent_display:<18} "
                f"{cost_str:>8} {format_tokens(s.input_tokens):>8} "
                f"{format_tokens(s.output_tokens):>8}  {time_str}"
            )
        return "\n".join(lines)


class ToolUsagePanel(Static):
    """Tool invocation counts."""

    data: reactive[dict[str, int]] = reactive(dict)

    def render(self) -> str:
        if not self.data:
            return "[dim]No tool data[/]"
        lines = ["[bold]Tool Usage (top 12)[/]"]
        lines.append("[dim]" + "─" * 45 + "[/]")
        max_count = max(self.data.values()) if self.data else 1
        for name, count in list(self.data.items())[:12]:
            bar_len = int(count / max_count * 20) if max_count > 0 else 0
            bar = "█" * bar_len + "░" * (20 - bar_len)
            lines.append(f"  {name:<25} {bar} {count:>5}")
        return "\n".join(lines)


class OpenCodeDashboard(App[None]):
    """Interactive TUI dashboard for OpenCode session monitoring."""

    TITLE = "OpenCode Dashboard"
    SUB_TITLE = "Sessions · Costs · Agents · Models"

    CSS = """
    Screen {
        layout: vertical;
    }

    #overview {
        height: 1;
        background: $accent-darken-2;
        padding: 0 1;
        dock: top;
    }

    #main-content {
        height: 1fr;
    }

    #left-panel {
        width: 1fr;
        height: 100%;
    }

    #right-panel {
        width: 1fr;
        height: 100%;
    }

    #model-table {
        height: auto;
        max-height: 14;
        border: solid $primary;
        margin: 0 1;
        padding: 0 1;
    }

    #agent-table {
        height: auto;
        max-height: 18;
        border: solid $success;
        margin: 0 1;
        padding: 0 1;
    }

    #daily-chart {
        height: auto;
        max-height: 20;
        border: solid $warning;
        margin: 0 1;
        padding: 0 1;
    }

    #subagent-tree {
        height: auto;
        max-height: 16;
        border: solid $error;
        margin: 0 1;
        padding: 0 1;
    }

    #session-list {
        height: 1fr;
        border: solid $accent;
        margin: 0 1;
        padding: 0 1;
        overflow-y: auto;
    }

    #tool-usage {
        height: auto;
        max-height: 16;
        border: solid $secondary;
        margin: 0 1;
        padding: 0 1;
    }

    #status-bar {
        height: 1;
        background: $accent-darken-2;
        dock: bottom;
        padding: 0 1;
    }
    """

    BINDINGS = [
        Binding("q", "quit", "Quit"),
        Binding("r", "refresh", "Refresh"),
        Binding("1", "show_overview", "Overview"),
        Binding("2", "show_models", "Models"),
        Binding("3", "show_agents", "Agents"),
        Binding("4", "show_daily", "Daily"),
        Binding("f", "toggle_fullscreen", "Fullscreen", priority=True),
    ]

    auto_refresh: reactive[bool] = reactive(True)
    refresh_interval: reactive[int] = reactive(30)
    last_refresh: reactive[str] = reactive("never")

    def compose(self) -> ComposeResult:
        yield Header()
        yield OverviewPanel(id="overview")
        with Horizontal(id="main-content"):
            with VerticalScroll(id="left-panel"):
                yield ModelCostTable(id="model-table")
                yield AgentCostTable(id="agent-table")
                yield ToolUsagePanel(id="tool-usage")
            with VerticalScroll(id="right-panel"):
                yield DailyCostChart(id="daily-chart")
                yield SubagentTreePanel(id="subagent-tree")
                yield SessionList(id="session-list")
        yield Label("[dim]Press q=quit r=refresh f=fullscreen[/]  ", id="status-bar")
        yield Footer()

    def on_mount(self) -> None:
        self.refresh_all()
        self.set_interval(30, self.auto_refresh_tick)

    def auto_refresh_tick(self) -> None:
        if self.auto_refresh:
            self.refresh_all()

    def refresh_all(self) -> None:
        try:
            overview = get_overview()
            models = get_model_costs()
            agents = get_agent_costs()
            daily = get_daily_costs(14)
            sessions = get_sessions(limit=30)
            trees = get_subagent_trees()
            tools = get_tool_usage()

            self.query_one("#overview", OverviewPanel).data = overview
            self.query_one("#model-table", ModelCostTable).data = models
            self.query_one("#agent-table", AgentCostTable).data = agents
            self.query_one("#daily-chart", DailyCostChart).data = daily
            self.query_one("#session-list", SessionList).data = sessions
            self.query_one("#subagent-tree", SubagentTreePanel).data = trees
            self.query_one("#tool-usage", ToolUsagePanel).data = tools

            self.last_refresh = datetime.now(tz=timezone.utc).strftime("%H:%M:%S")
            status = self.query_one("#status-bar", Label)
            status.update(
                f"[dim]Last refresh: {self.last_refresh}  |  "
                f"Auto-refresh: {'ON' if self.auto_refresh else 'OFF'} ({self.refresh_interval}s)  |  "
                f"Press q=quit r=refresh f=fullscreen[/]"
            )
        except Exception as e:
            self.query_one("#status-bar", Label).update(f"[bold red]Error: {e}[/]")

    def action_refresh(self) -> None:
        self.refresh_all()

    def action_toggle_fullscreen(self) -> None:
        self.fullscreen = not self.fullscreen


if __name__ == "__main__":
    OpenCodeDashboard().run()

