def get_tool_usage() -> dict[str, int]:
    with _connect() as conn:
        rows = conn.execute(
            """
            SELECT data FROM part
            WHERE data LIKE '%"type":%'
            LIMIT 5000
            """
        ).fetchall()
        tool_counts: dict[str, int] = {}
        import json
        for r in rows:
            try:
                d = json.loads(r["data"])
                ptype = d.get("type", "")
                if ptype == "tool-invocation":
                    tool_name = d.get("toolInvocation", {}).get("toolName", "unknown")
                    tool_counts[tool_name] = tool_counts.get(tool_name, 0) + 1
            except (json.JSONDecodeError, TypeError, AttributeError):
                continue
        return dict(sorted(tool_counts.items(), key=lambda kv: kv[1], reverse=True))

